input.command:
cd /home/user/fortress/tmp/gate-batch-7/ladder && python3 microgpt-phase.py > microgpt-phase-py.txt 2>&1; echo rc=$?; cat microgpt-phase-py.txt; cd /home/user/fortress && cat >> /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/gatefns.sh <<'EOF'

ladder_filter () { sed -E 's/Operation took [0-9.]+ms/Operation took <time>ms/' "$1" ; }
ladder_compare () {               # ladder_compare <baseline-dir> <now-dir>; prints one DOWN, UP, NEW, MISSING or STDOUT line per moved file, and nothing when nothing moved
    local B="$1" N="$2" key
    awk -F'\t' '
      function rank(p,   r) { r["parse"]=1; r["disambiguate"]=2; r["typecheck"]=3; r["codegen"]=4;
                              r["link"]=5; r["run"]=6; r["pass"]=7; return r[p] + 0 }
      FNR == NR { if (FNR > 1) b[$1 "/" $2] = $4 ; next }
      FNR > 1 {
          k = $1 "/" $2
          if (!(k in b))                  { print "NEW\t" k "\t" $4 ; next }
          if (rank($4) < rank(b[k]))      { print "DOWN\t" k "\t" b[k] " -> " $4 }
          else if (rank($4) > rank(b[k])) { print "UP\t" k "\t" b[k] " -> " $4 }
      }' "$B/ladder.tsv" "$N/ladder.tsv"
    tail -n +2 "$B/pass-list.txt" | cut -f1 | while IFS= read -r key ; do
        [ -n "$key" ] || continue
        if [ ! -f "$N/raw/$key.run" ] ; then printf 'MISSING\t%s\n' "$key" ; continue ; fi
        if ! diff -q <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") >/dev/null ; then
            printf 'STDOUT\t%s\n' "$key"
            diff <(ladder_filter "$B/raw/$key.run") <(ladder_filter "$N/raw/$key.run") | sed 's/^/    /' | head -8
        fi
    done
}
mg_phases () { awk -F'|' '/^\| *[0-9]+ *\| *`/ { gsub(/[` ]/, "", $3); gsub(/ /, "", $4); print $3 "\t" $4 }' "$1" ; }
EOF
source explorations/experiment/env.sh && source /tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/gatefns.sh && ladder_compare explorations/compile-ladder/baseline-2026-09-19 tmp/gate-batch-7/ladder > tmp/gate-batch-7/ladder/comparison.txt; echo "ladder_compare rc=$? lines=$(wc -l < tmp/gate-batch-7/ladder/comparison.txt)"; cat tmp/gate-batch-7/ladder/comparison.txt; diff <(mg_phases explorations/compile-ladder/baseline-2026-09-19/microgpt-phase.md) <(mg_phases tmp/gate-batch-7/ladder/microgpt-phase.md) > tmp/gate-batch-7/ladder/microgpt-comparison.txt; echo "mg diff rc=$? lines=$(wc -l < tmp/gate-batch-7/ladder/microgpt-comparison.txt)"; cat tmp/gate-batch-7/ladder/microgpt-comparison.txt; mg_phases tmp/gate-batch-7/ladder/microgpt-phase.md | wc -l

